import{_ as l,l as o,o as e,c as n,v as t,p as s,x as i,d as c,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"链表与局部性代价","description":"","frontmatter":{"title":"链表与局部性代价","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/linked-list-locality.md","filePath":"cs/linked-list-locality.md","lastUpdated":1789023840000}'),p={name:"cs/linked-list-locality.md"};function m(_,a,A,T,u,f){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="链表与局部性代价" tabindex="-1">链表与局部性代价 <a class="header-anchor" href="#链表与局部性代价" aria-label="Permalink to &quot;链表与局部性代价&quot;">​</a></h1><div class="epigraph"><p>指针把插入从搬移改成改两三条边；下一次访问的地址不再是加一个常量，cache 与预取都失去对象。</p><footer>—— 据 Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms；Hennessy and Patterson 存储器层次 整理</footer></div><p><a href="/cs/dynamic-array">上一课</a>把按下标读做成 \\(\\Theta(1)\\)，中间插入要搬 \\(n\\) 个元素。<a href="/cs/locality-principle">局部性原理</a>依赖「下一块地址可预测」。本课不重讲基址加偏移。缺口是另一种表示：节点散落在堆上，用指针串成序列，从而在已知节点处插入删除 \\(\\Theta(1)\\) 步，并显式付出随机访问与空间局部性。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数组合同里没有「在这个元素后面塞一个」的廉价操作。把元素做成节点 <code>{值, 后继}</code>，插入不再搬移。缺口不是再定义序列 ADT，而是承认：<strong>步数上的 \\(O(1)\\) 插入，用的是打散的地址</strong>，与 cache 行、预取、NUMA 本地都作对。</p><p>单向链表找不到前驱；双向用再一个指针换。本课以单向为主，点名双向。不引入跳表的多层指针。</p><p><span class="marginnote">指针追逐是 cache 缺失分类里接近必现的容量/强制混合：工作集是节点集合，空间局部性近乎零。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>节点动态分配。头指针代表表。在已知节点 \\(p\\) 后插入：\\(q.\\mathrm{next}=p.\\mathrm{next},\\ p.\\mathrm{next}=q\\)，常数次 store。按下标找第 \\(i\\) 个必须走 \\(i\\) 步，合同变成 \\(\\Theta(i)\\)，不再是数组的 \\(\\Theta(1)\\)。</p>',9)),(e(),s(h,null,{default:i(()=>[d(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20H%5B%22%E5%A4%B4%22%5D%20--%3E%20A%5B%22%E8%8A%82%E7%82%B9%20a%22%5D%0A%20%20A%20--%3E%20B%5B%22%E8%8A%82%E7%82%B9%20b%22%5D%0A%20%20B%20--%3E%20C%5B%22%E8%8A%82%E7%82%B9%20c%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>顺序遍历的渐近仍 \\(\\Theta(n)\\)，但每步可能 miss 一次 DRAM，常数比数组扫大一个层次存储器倍数。ADT 课开始时说的「代价含常数」在这里具体化。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>链表适合中间频繁插入、几乎不按下标跳的工作负载。栈和队列可以用链表实现，也可以用数组；后课按操作选。<a href="/cs/calling-convention-stack">调用约定与栈</a>的硬件栈是连续数组，不是堆上链表——那是因为调用需要空间局部性与地址计算。</p><p>释放节点必须避免悬挂：删掉的后继要从链上摘下。这是表示不变式，不是 ISA 异常。头插与尾插改变的是哪根指针，合同仍是序列，只是端点不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把链表写成「动态数组的替代品」：随机访问需求仍该用数组。也不引入 XOR 链表等压缩技巧。并行下无锁链表是附录。</p><p>后课默认：序列有两种主表示。栈作为 ADT，限制只在一端操作，表示可以是数组顶或链表头。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>已知位置插入删除 \\(\\Theta(1)\\) 步；按下标访问 \\(\\Theta(i)\\)。</li><li>地址无步长，空间局部性差，cache 常数大。</li><li>栈把序列合同收窄到一端，下一课只谈那一端。</li><li>需要随机访问时仍用数组，不要把链表当动态表的替代品。</li><li>出处：Cormen et al. 链表；与 <em>CA:AQA</em> 局部性对照。</li></ul>',9))])}const b=l(p,[["render",m]]);export{x as __pageData,b as default};
